-- Generated by scripts/feature-post.mjs. Makes "black-friday-first-time-buyers" the featured Industry LoogoBlog
-- post. Clear first, then set, so posts_one_featured never sees two rows.
UPDATE "posts" SET "featured" = false WHERE "featured" AND "slug" <> 'black-friday-first-time-buyers';
UPDATE "posts" SET "featured" = true WHERE "slug" = 'black-friday-first-time-buyers' AND "status" = 'published';
